nextflow_process {

    name "Test Process BAM2FASTX_BAM2FASTQ"
    script "../main.nf"
    process "BAM2FASTX_BAM2FASTQ"

    tag "modules"
    tag "modules_nfcore"
    tag "bam2fastx"
    tag "bam2fastx/bam2fastq"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('bam'), file('index') ]
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated. Please use nf-core/modules/pbtk/bam2fastq") }
            )
        }
    }
}
